INSERT INTO `pipeline_posts` VALUES ('1111aaaa-1111-1111-1111-000000000001',NULL,'bf8cb7d6-5022-11f1-8ddd-005056c00001','A complete workflow to build, test, and deploy .NET 8 apps using GitHub Actions.',1,'2026-05-15 12:55:59','2026-05-15 12:55:59'),('1111aaaa-1111-1111-1111-000000000002',NULL,'bf8cbb82-5022-11f1-8ddd-005056c00001','Pipeline configuration to automatically pack and push NuGet packages on release.',1,'2026-05-15 12:55:59','2026-05-15 12:55:59'),('2222bbbb-2222-2222-2222-000000000001',NULL,'bf8cbceb-5022-11f1-8ddd-005056c00001','A standardized declarative Jenkinsfile for any Dockerized application.',2,'2026-05-15 12:55:59','2026-05-15 12:55:59'),('2222bbbb-2222-2222-2222-000000000002',NULL,'bf8cc14e-5022-11f1-8ddd-005056c00001','Optimized multi-stage Docker build to keep images lightweight.',1,'2026-05-15 12:55:59','2026-05-15 12:55:59'),('2222bbbb-2222-2222-2222-000000000003',NULL,'bf8cc213-5022-11f1-8ddd-005056c00001','Setup script and examples for creating a Jenkins Shared Library.',1,'2026-05-15 12:55:59','2026-05-15 12:55:59'),('3333cccc-3333-3333-3333-000000000001',NULL,'bf8cc2ac-5022-11f1-8ddd-005056c00001','GitOps workflow using ArgoCD to sync Kubernetes manifests.',3,'2026-05-15 12:55:59','2026-05-15 12:55:59'),('3333cccc-3333-3333-3333-000000000002',NULL,'bf8cc393-5022-11f1-8ddd-005056c00001','Automated Helm chart deployment for Prometheus and Grafana stack.',1,'2026-05-15 12:55:59','2026-05-15 12:55:59'),('4444dddd-4444-4444-4444-000000000001',NULL,'bf8cc472-5022-11f1-8ddd-005056c00001','Terraform code to spin up a fully configured AWS EKS cluster.',2,'2026-05-15 12:55:59','2026-05-15 12:55:59'),('4444dddd-4444-4444-4444-000000000002',NULL,'bf8cc57f-5022-11f1-8ddd-005056c00001','CI/CD pipeline applying Terraform scripts securely via GitHub Actions.',1,'2026-05-15 12:55:59','2026-05-15 12:55:59'),('4444dddd-4444-4444-4444-000000000003',NULL,'bf8cc61d-5022-11f1-8ddd-005056c00001','Module to automate S3 bucket creation with strict security policies.',1,'2026-05-15 12:55:59','2026-05-15 12:55:59'),('5555eeee-5555-5555-5555-000000000001',NULL,'bf8cc6a9-5022-11f1-8ddd-005056c00001','`.gitlab-ci.yml` template customized for Node.js projects.',1,'2026-05-15 12:55:59','2026-05-15 12:55:59'),('5555eeee-5555-5555-5555-000000000002',NULL,'bf8cc73e-5022-11f1-8ddd-005056c00001','Complex pipeline handling multiple microservices within a monorepo.',2,'2026-05-15 12:55:59','2026-05-15 12:55:59'),('6666ffff-6666-6666-6666-000000000001',NULL,'bf8cc82f-5022-11f1-8ddd-005056c00001','Integration of Cypress tests running against a staging environment.',1,'2026-05-15 12:55:59','2026-05-15 12:55:59'),('6666ffff-6666-6666-6666-000000000002',NULL,'bf8cc8be-5022-11f1-8ddd-005056c00001','Fast and reliable Vitest setup for Vue 3 component testing.',1,'2026-05-15 12:55:59','2026-05-15 12:55:59'),('a1000005-0000-0000-0000-000000000005',NULL,'b2000001-0000-0000-0000-000000000001','GitLab CI pipeline for a Node.js application that installs dependencies, runs tests, builds a Docker image, and pushes it for deployment.',1,'2026-04-01 14:00:00','2026-04-01 14:00:00'),('a89145e1-f773-4bbc-9aee-cc5fa861112b',NULL,'dfbd2abf-4c84-4b12-8003-ef19e361e81b','<p>Hướng dẫn thiết lập một CI Pipeline đơn giản nhưng hiệu quả cho dự án .NET 8 (sử dụng GitHub Actions/GitLab CI).</p><blockquote><p><strong>Các luồng (jobs) chính trong Pipeline:</strong></p><ul><li><p><strong>Setup:</strong> Chuẩn bị môi trường chạy với .NET 8 SDK.</p></li><li><p><strong>Restore &amp; Build:</strong> Thực thi lệnh <code>dotnet restore</code> và biên dịch mã nguồn mà không làm thay đổi lock file.</p></li><li><p><strong>Testing:</strong> Chạy toàn bộ các test case trong project với <code>dotnet test</code> để đảm bảo chất lượng code.</p></li><li><p><strong>Publish (Tùy chọn):</strong> Đóng gói ứng dụng (Artifacts) sẵn sàng cho bước triển khai (CD).</p></li></ul></blockquote><p></p>',12,'2026-04-24 07:17:23','2026-04-28 16:11:10');
/*!40000 ALTER TABLE `pipeline_posts` ENABLE KEYS */;
UNLOCK TABLES;

