INSERT INTO `pipeline_versions` VALUES ('035fb46f-b119-4850-8efa-936de95d0a02','a89145e1-f773-4bbc-9aee-cc5fa861112b',6,'name: CI\r\n\r\n# Pipeline tự động kích hoạt khi code mới được đẩy lên nhánh \'main\'\r\non:\r\n  push:\r\n    branches: [ \"main\" ]\r\n  pull_request:\r\n    branches: [ \"main\" ]\r\n\r\njobs:\r\n  build-and-test:\r\n    runs-on: ubuntu-latest\r\n\r\n    steps:\r\n    # Bước 1: Kéo code từ repository về môi trường chạy\r\n    - name: Checkout Code\r\n      uses: actions/checkout@v4\r\n\r\n    # Bước 2: Cài đặt môi trường .NET 8\r\n    - name: Setup .NET 8\r\n      uses: actions/setup-dotnet@v4\r\n      with:\r\n        dotnet-version: 8.0.x\r\n\r\n    # Bước 3: Tải các thư viện (packages) cần thiết\r\n    - name: Restore dependencies\r\n      run: dotnet restore\r\n\r\n    # Bước 4: Build project theo cấu hình Release\r\n    - name: Build project\r\n      run: dotnet build --no-restore --configuration Release\r\n\r\n    # Bước 5: Chạy Unit Test (nếu có)\r\n    - name: Run tests\r\n      run: dotnet test --no-build --verbosity normal','Initial version','6d49c8d7-9dce-4274-9f75-b0f2f911a1b9','2026-04-28 10:10:51'),('0462e396-dd5c-4c7a-bc03-5e084e6c08d2','a89145e1-f773-4bbc-9aee-cc5fa861112b',9,'name: CI-test\r\n\r\n# Pipeline tự động kích hoạt khi code mới được đẩy lên nhánh \'main\'\r\non:\r\n  push:\r\n    branches: [ \"main\" ]\r\n  pull_request:\r\n    branches: [ \"main\" ]\r\n\r\njobs:\r\n  build-and-test:\r\n    runs-on: ubuntu-latest\r\n\r\n    steps:\r\n    # Bước 1: Kéo code từ repository về môi trường chạy\r\n    - name: Checkout Code\r\n      uses: actions/checkout@v4\r\n\r\n    # Bước 2: Cài đặt môi trường .NET 8\r\n    - name: Setup .NET 8\r\n      uses: actions/setup-dotnet@v4\r\n      with:\r\n        dotnet-version: 8.0.x\r\n\r\n    # Bước 3: Tải các thư viện (packages) cần thiết\r\n    - name: Restore dependencies\r\n      run: dotnet restore\r\n\r\n    # Bước 4: Build project theo cấu hình Release\r\n    - name: Build project\r