@v4\r\n      with:\r\n        dotnet-version: 8.0.x\r\n\r\n    # Bước 3: Tải các thư viện (packages) cần thiết\r\n    - name: Restore dependencies\r\n      run: dotnet restore\r\n\r\n    # Bước 4: Build project theo cấu hình Release\r\n    - name: Build project\r\n      run: dotnet build --no-restore --configuration Release\r\n\r\n    # Bước 5: Chạy Unit Test (nếu có)\r\n    - name: Run tests\r\n      run: dotnet test --no-build --verbosity normal','Initial version','6d49c8d7-9dce-4274-9f75-b0f2f911a1b9','2026-04-28 10:06:20'),('5ba791f4-c2c4-4890-9802-384f5280c935','a89145e1-f773-4bbc-9aee-cc5fa861112b',7,'name: CI-test\r\n\r\n# Pipeline tự động kích hoạt khi code mới được đẩy lên nhánh \'main\'\r\non:\r\n  push:\r\n    branches: [ \"main\" ]\r\n  pull_request:\r\n    branches: [ \"main\" ]\r\n\r\njobs:\r\n  build-and-test:\r\n    runs-on: ubuntu-latest\r\n\r\n    steps:\r\n    # Bước 1: Kéo code từ repository về môi trường chạy\r\n    - name: Checkout Code\r\n      uses: actions/checkout@v4\r\n\r\n    # Bước 2: Cài đặt môi trường .NET 8\r\n    - name: Setup .NET 8\r\n      uses: actions/setup-dotnet@v4\r\n      with:\r\n        dotnet-version: 8.0.x\r\n\r\n    # Bước 3: Tải các thư viện (packages) cần thiết\r\n    - name: Restore dependencies\r\n      run: dotnet restore\r\n\r\n    # Bước 4: Build project theo cấu hình Release\r\n    - name: Build project\r\n      run: dotnet build --no-restore --configuration Release\r\n\r\n    # Bước 5: Chạy Unit Test (nếu có)\r\n    - name: Run tests\r\n      run: dotnet test --no-build --verbosity normal','Initial version','6d49c8d7-9dce-4274-9f75-b0f2f911a1b9','2026-04-28 10:16:13'),('5f527473-afca-4a78-8c37-cf4d700cbb23','a89145e1-f773-4bbc-9aee-cc5fa861112b',10,'name: CI-test\r\n\r\n# Pipeline tự động kích hoạt khi code mới được đẩy lên nhánh \'main\'\r\non:\r\n  push:\r\n    branches: [ \"main\" ]\r\n  pull_request:\r\n    branches: [ \"main\" ]\r\n\r\njobs:\r\n  build-and-test:\r\n    runs-on: ubuntu-latest\r\n\r\n    steps:\r\n    # Bước 1: Kéo code từ repository về môi trường chạy\r\n    - name: Checkout Code\r\n      uses: actions/checkout@v4\r\n\r\n    # Bước 2: Cài đặt môi trường .NET 8\r\n    - name: Setup .NET 8\r\n      uses: actions/setup-dotnet@v4\r\n      with:\r\n        dotnet-version: 8.0.x\r\n\r\n    # Bước 3: Tải các thư viện (packages) cần thiết\r\n    - name: Restore dependencies\r\n      run: dotnet restore\r\n\r\n    # Bước 4: Build project theo cấu hình Release\r\n    - name: Build project\r\n      run: dotnet build --no-restore --configuration Release\r\n\r\n    # Bước 5: Chạy Unit Test (nếu có)\r\n    - name: Run tests\r\n      run: dotnet test --no-build --verbosity normal','Initial version','6d49c8d7-9dce-4274-9f75-b0f2f911a1b9','2026-04-28 16:07:10'),('6c0c23e7-95f4-4821-9322-81f74c45f980','a89145e1-f773-4bbc-9aee-cc5fa861112b',2,'name: .NET 8 Simple CI\r\n\r\n# Pipeline sẽ tự động kích hoạt khi có code mới đẩy lên nhánh \'main\'\r\non:\r\n  push:\r\n    branches: [ \"main\" ]\r\n  pull_request:\r\n    branches: [ \"main\" ]\r\n\r\njobs:\r\n  build-and-test:\r\n    runs-on: ubuntu-latest\r\n\r\n    steps:\r\n    # Bước 1: Kéo code từ repository về môi trường chạy\r\n    - name: Checkout Code\r\n      uses: actions/checkout@v4\r\n\r\n    # Bước 2: Cài đặt môi trường .NET 8\r\n    - name: Setup .NET 8\r\n      uses: actions/setup-dotnet@v4\r\n      with:\r\n        dotnet-version: 8.0.x\r\n\r\n    # Bước 3: Tải các thư viện (packages) cần thiết\r\n    - name: Restore dependencies\r\n      run: dotnet restore\r\n\r\n    # Bước 4: Build project theo cấu hình Release\r\n    - name: Build project\r\n      run: dotnet build --no-restore --configuration Release\r\n\r\n    # Bước 5: Chạy Unit Test (nếu có)\r\n    - name: Run tests\r\n      run: dotnet test --no-build --verbosity normal','Initial version','6d49c8d7-9dce-4274-9f75-b0f2f911a1b9','2026-04-28 10:00:34'),('7830a3a7-ab92-4199-8594-06b466b0da6d','a89145e1-f773-4bbc-9aee-cc5fa861112b',12,'name: CI-test\r\n\r\n# Pipeline tự động kích hoạt khi code mới được đẩy lên nhánh \'main\'\r\non:\r\n  push:\r\n    branches: [ \"main\" ]\r\n  pull_request:\r\n    branches: [ \"main\" ]\r\n\r\njobs:\r\n  build-and-test:\r\n    runs-on: ubuntu-latest\r\n\r\n    steps:\r\n    # Bước 1: Kéo code từ repository về môi trường chạy\r\n    - name: Checkout Code\r\n      uses: actions/checkout@v4\r\n\r\n    # Bước 2: Cài đặt môi trường .NET 8\r\n    - name: Setup .NET 8\r\n      uses: actions/setup-dotnet@v4\r\n      with:\r\n        dotnet-version: 8.0.x\r\n\r\n    # Bước 3: Tải các thư viện (packages) cần thiết\r\n    - name: Restore dependencies\r\n      run: dotnet restore\r\n\r\n    # Bước 4: Build project theo cấu hình Release\r\n    - name: Build project\r\n      run: dotnet build --no-restore --configuration Release\r\n\r\n    # Bước 5: Chạy Unit Test (nếu có)\r\n    - name: Run tests\r\n      run: dotnet test --no-build --verbosity normal','Initial version','6d49c8d7-9dce-4274-9f75-b0f2f911a1b9','2026-04-28 16:11:10'),('98d3ee81-f0d4-4417-9157-952258b0d4e0','a89145e1-f773-4bbc-9aee-cc5fa861112b',3,'name: .NET 8 Simple CI\r\n\r\n# Pipeline tự động kích hoạt khi có code mới đẩy lên nhánh \'main\'\r\non:\r\n  push:\r\n    branches: [ \"main\" ]\r\n  pull_request:\r\n    branches: [ \"main\" ]\r\n\r\njobs:\r\n  build-and-test:\r\n    runs-on: ubuntu-latest\r\n\r\n    steps:\r\n    # Bước 1: Kéo code từ repository về môi trường chạy\r\n    - name: Checkout Code\r\n      uses: actions/checkout@v4\r\n\r\n    # Bước 2: Cài đặt môi trường .NET 8\r\n    - name: Setup .NET 8\r\n      uses: actions/setup-dotnet@v4\r\n      with:\r\n        dotnet-version: 8.0.x\r\n\r\n    # Bước 3: Tải các thư viện (packages) cần thiết\r\n    - name: Restore dependencies\r\n      run: dotnet restore\r\n\r\n    # Bước 4: Build project theo cấu hình Release\r\n    - name: Build project\r\n      run: dotnet build --no-restore --configuration Release\r\n\r\n    # Bước 5: Chạy Unit Test (nếu có)\r\n    - name: Run tests\r\n      run: dotnet test --no-build --verbosity normal','Initial version','6d49c8d7-9dce-4274-9f75-b0f2f911a1b9','2026-04-28 10:00:58'),('b2000001-0000-0000-0000-000000000001','a1000005-0000-0000-0000-000000000005',1,'stages:\n  - install\n  - test\n  - dockerize\n  - deploy\n\nimage: node:20\n\ncache:\n  paths:\n    - node_modules/\n\ninstall:\n  stage: install\n  script:\n    - npm ci\n\ntest:\n  stage: test\n  script:\n    - npm test\n\ndocker_build:\n  stage: dockerize\n  image: docker:24\n  services:\n    - docker:24-dind\n  script:\n    - docker build -t registry.example.com/node-app:$CI_COMMIT_SHORT_SHA .\n    - docker push registry.example.com/node-app:$CI_COMMIT_SHORT_SHA\n\ndeploy_prod:\n  stage: deploy\n  script:\n    - echo \"Deploying image to production environment...\"','Initial version','55555555-5555-5555-5555-555555555555','2026-04-01 14:05:00'),('bf8cb7d6-5022-11f1-8ddd-005056c00001','1111aaaa-1111-1111-1111-000000000001',1,'name: .NET CI\non:\n  push:\n    branches: [ \"main\" ]\njobs:\n  build:\n    runs-on: ubuntu-latest\n    steps:\n    - uses: actions/checkout@v4\n    - name: Setup .NET\n      uses: actions/setup-dotnet@v4\n      with:\n        dotnet-version: 8.0.x\n    - name: Restore dependencies\n      run: dotnet restore\n    - name: Build\n      run: dotnet build --no-restore\n    - name: Test\n      run: dotnet test --no-build --verbosity normal','Initial .NET 8 CI template','11111111-1111-1111-1111-111111111111','2026-05-15 12:55:59'),('bf8cbb82-5022-11f1-8ddd-005056c00001','1111aaaa-1111-1111-1111-000000000002',1,'name: Publish NuGet\non:\n  release:\n    types: [published]\njobs:\n  publish:\n    runs-on: ubuntu-latest\n    steps:\n    - uses: actions/checkout@v4\n    - run: dotnet pack -c Release -o out\n    - run: dotnet nuget push out/*.nupkg --api-key ${{ secrets.NUGET_API_KEY }} --source https://api.nuget.org/v3/index.json','Added automated NuGet push on release','11111111-1111-1111-1111-111111111111','2026-05-15 12:55:59'),('bf8cbceb-5022-11f1-8ddd-005056c00001','2222bbbb-2222-2222-2222-000000000001',1,'pipeline {\n    agent any\n    environment {\n        DOCKER_IMAGE = \'myapp/frontend:latest\'\n    }\n    stages {\n        stage(\'Build\') {\n            steps {\n                sh \'docker build -t ${DOCKER_IMAGE} .\'\n            }\n        }\n        stage(\'Push\') {\n            steps {\n                withCredentials([string(credentialsId: \'docker-hub\', variable: \'DOCKER_PASS\')]) {\n                    sh \'echo $DOCKER_PASS | docker login -u myapp --password-stdin\'\n                    sh \'docker push ${DOCKER_IMAGE}\'\n                }\n            }\n        }\n    }\n}','Standard declarative Jenkinsfile','22222222-2222-2222-2222-222222222222','2026-05-15 12:55:59'),('bf8cc14e-5022-11f1-8ddd-005056c00001','2222bbbb-2222-2222-2222-000000000002',1,'# Build stage\nFROM node:18-alpine AS builder\nWORKDIR /app\nCOPY package*.json ./\nRUN npm ci\nCOPY . .\nRUN npm run build\n\n# Production stage\nFROM nginx:alpine\nCOPY --from=builder /app/dist /usr/share/nginx/html\nEXPOSE 80\nCMD [\"nginx\", \"-g\", \"daemon off;\"]','Optimized image size using multi-stage build','22222222-2222-2222-2222-222222222222','2026-05-15 12:55:59'),('bf8cc213-5022-11f1-8ddd-005056c00001','2222bbbb-2222-2222-2222-000000000003',1,'// vars/standardBuild.groovy\ndef call(Map config = [:]) {\n    pipeline {\n        agent any\n        stages {\n            stage(\'Setup\') {\n                steps {\n                    echo \"Starting build for ${config.projectName}\"\n                }\n            }\n        }\n    }\n}','Initial shared library script','22222222-2222-2222-2222-222222222222','2026-05-15 12:55:59'),('bf8cc2ac-5022-11f1-8ddd-005056c00001','3333cccc-3333-3333-3333-000000000001',1,'apiVersion: argoproj.io/v1alpha1\nkind: Application\nmetadata:\n  name: my-k8s-app\n  namespace: argocd\nspec:\n  project: default\n  source:\n    repoURL: \'https://github.com/my-org/my-k8s-manifests.git\'\n    targetRevision: HEAD\n    path: k8s/production\n  destination:\n    server: \'https://kubernetes.default.svc\'\n    namespace: production\n  syncPolicy:\n    automated:\n      prune: true\n      selfHeal: true','GitOps config for Production environment','33333333-3333-3333-3333-333333333333','2026-05-15 12:55:59'),('bf8cc393-5022-11f1-8ddd-005056c00001','3333cccc-3333-3333-3333-000000000002',1,'# values.yaml overrides for prometheus-community/kube-prometheus-stack\ngrafana:\n  adminPassword: \"secure-password-here\"\n  ingress:\n    enabled: true\n    hosts:\n      - grafana.mycompany.internal\nprometheus:\n  prometheusSpec:\n    retention: 15d','Helm chart values for monitoring stack','33333333-3333-3333-3333-333333333333','2026-05-15 12:55:59'),('bf8cc472-5022-11f1-8ddd-005056c00001','4444dddd-4444-4444-4444-000000000001',1,'module \"eks\" {\n  source  = \"terraform-aws-modules/eks/aws\"\n  version = \"~> 20.0\"\n\n  cluster_name    = \"production-cluster\"\n  cluster_version = \"1.29\"\n\n  vpc_id                   = module.vpc.vpc_id\n  subnet_ids               = module.vpc.private_subnets\n  control_plane_subnet_ids = module.vpc.intra_subnets\n\n  eks_managed_node_groups = {\n    general = {\n      instance_types = [\"t3.medium\"]\n      min_size     = 2\n      max_size     = 5\n      desired_size = 2\n    }\n  }\n}','EKS provisioning script with managed nodes','44444444-4444-4444-4444-444444444444','2026-05-15 12:55:59'),('bf8cc57f-5022-11f1-8ddd-005056c00001','4444dddd-4444-4444-4444-000000000002',1,'name: Terraform Apply\non:\n  push:\n    branches: [ main ]\njobs:\n  terraform:\n    runs-on: ubuntu-latest\n    steps:\n    - uses: actions/checkout@v4\n    - uses: hashicorp/setup-terraform@v3\n    - name: Terraform Init\n      run: terraform init\n    - name: Terraform Plan\n      run: terraform plan -out=tfplan\n    - name: Terraform Apply\n      run: terraform apply -auto-approve tfplan','Simple Terraform automation pipeline','44444444-4444-4444-4444-444444444444','2026-05-15 12:55:59'),('bf8cc61d-5022-11f1-8ddd-005056c00001','4444dddd-4444-4444-4444-000000000003',1,'resource \"aws_s3_bucket\" \"secure_bucket\" {\n  bucket = \"my-secure-data-bucket-123\"\n}\n\nresource \"aws_s3_bucket_public_access_block\" \"block\" {\n  bucket = aws_s3_bucket.secure_bucket.id\n\n  block_public_acls       = true\n  block_public_policy     = true\n  ignore_public_acls      = true\n  restrict_public_buckets = true\n}','S3 bucket creation with Public Access blocked','44444444-4444-4444-4444-444444444444','2026-05-15 12:55:59'),('bf8cc6a9-5022-11f1-8ddd-005056c00001','5555eeee-5555-5555-5555-000000000001',1,'image: node:18-alpine\n\nstages:\n  - test\n  - build\n\ncache:\n  paths:\n    - node_modules/\n\ntest_job:\n  stage: test\n  script:\n    - npm ci\n    - npm run test\n\nbuild_job:\n  stage: build\n  script:\n    - npm run build\n  artifacts:\n    paths:\n      - dist/','Basic Node.js GitLab template','55555555-5555-5555-5555-555555555555','2026-05-15 12:55:59'),('bf8cc73e-5022-11f1-8ddd-005056c00001','5555eeee-5555-5555-5555-000000000002',1,'frontend-build:\n  stage: build\n  script:\n    - cd packages/frontend\n    - npm ci && npm run build\n  rules:\n    - changes:\n        - packages/frontend/**/*\n\nbackend-build:\n  stage: build\n  script:\n    - cd packages/backend\n    - npm ci && npm run build\n  rules:\n    - changes:\n        - packages/backend/**/*','Rules implemented for monorepo paths','55555555-5555-5555-5555-555555555555','2026-05-15 12:55:59'),('bf8cc82f-5022-11f1-8ddd-005056c00001','6666ffff-6666-6666-6666-000000000001',1,'name: Cypress Tests\non: [push]\njobs:\n  cypress-run:\n    runs-on: ubuntu-latest\n    steps:\n      - name: Checkout\n        uses: actions/checkout@v4\n      - name: Cypress run\n        uses: cypress-io/github-action@v6\n        with:\n          build: npm run build\n          start: npm run start\n          wait-on: \'http://localhost:3000\'','Automated Cypress E2E testing action','