INSERT INTO `question_posts` VALUES ('1111aaaa-1111-1111-1111-000000000003','I am trying to cache NuGet packages to speed up my GitHub Actions, but it seems to redownload them every time. Any working examples?',NULL,NULL,'2026-05-15 12:55:59','2026-05-15 12:55:59'),('1111aaaa-1111-1111-1111-000000000004','What is the industry standard for managing secrets like DB connection strings in a .NET production app? Key Vault vs Environment Variables?',NULL,NULL,'2026-05-15 12:55:59','2026-05-15 12:55:59'),('1111aaaa-1111-1111-1111-000000000005','My self-hosted GitHub runner on an Ubuntu VM keeps disconnecting randomly after 24 hours. Where should I check the logs?',NULL,NULL,'2026-05-15 12:55:59','2026-05-15 12:55:59'),('2222bbbb-2222-2222-2222-000000000004','Locally my Docker build takes 2 mins, but on the Jenkins agent it takes 15 mins. Is it an IO issue or Docker cache missing?',NULL,NULL,'2026-05-15 12:55:59','2026-05-15 12:55:59'),('2222bbbb-2222-2222-2222-000000000005','How do you inject Jenkins secrets into a shell script block without exposing them in the console output?',NULL,NULL,'2026-05-15 12:55:59','2026-05-15 12:55:59'),('3333cccc-3333-3333-3333-000000000003','Should I use MaxSurge 25% or an absolute number for high-traffic API deployments in Kubernetes?',NULL,NULL,'2026-05-15 12:55:59','2026-05-15 12:55:59'),('3333cccc-3333-3333-3333-000000000004','What are the best tools (besides Datadog) to get alerts immediately when a K8s pod goes into CrashLoopBackOff?',NULL,NULL,'2026-05-15 12:55:59','2026-05-15 12:55:59'),('3333cccc-3333-3333-3333-000000000005','ArgoCD shows my application as \"Out of Sync\" even though the Git repo matches the cluster state exactly. How to debug?',NULL,NULL,'2026-05-15 12:55:59','2026-05-15 12:55:59'),('4444dddd-4444-4444-4444-000000000004','Is S3 + DynamoDB locking still the best practice for Terraform state, or should I migrate to Terraform Cloud?',NULL,NULL,'2026-05-15 12:55:59','2026-05-15 12:55:59'),('4444dddd-4444-4444-4444-000000000005','My `terraform apply` fails with \"Access Denied\" when creating an IAM role, but my user has AdministratorAccess. Why?',NULL,NULL,'2026-05-15 12:55:59','2026-05-15 12:55:59'),('5555eeee-5555-5555-5555-000000000003','I need Project A pipeline to trigger Project B pipeline and pass an artifact. Can this be done natively in GitLab CI?',NULL,NULL,'2026-05-15 12:55:59','2026-05-15 12:55:59'),('5555eeee-5555-5555-5555-000000000004','Should I cache `node_modules` directly or just the `~/.npm` folder in GitLab CI to save time?',NULL,NULL,'2026-05-15 12:55:59','2026-05-15 12:55:59'),('5555eeee-5555-5555-5555-000000000005','I have variables set in the UI, in `.gitlab-ci.yml`, and via API. Which one takes precedence if they share the same name?',NULL,NULL,'2026-05-15 12:55:59','2026-05-15 12:55:59'),('6666ffff-6666-6666-6666-000000000003','When writing component tests in Vitest, what is the cleanest way to mock a Pinia store without breaking reactivity?',NULL,NULL,'2026-05-15 12:55:59','2026-05-15 12:55:59'),('6666ffff-6666-6666-6666-000000000004','Some of my Cypress E2E tests pass locally but fail randomly in CI due to timeout issues. How do you handle flaky tests?',NULL,NULL,'2026-05-15 12:55:59','2026-05-15 12:55:59'),('6666ffff-6666-6666-6666-000000000005','Is it better to test Vue components deeply with all children rendered, or use shallow mounting to isolate the component?',NULL,NULL,'2026-05-15 12:55:59','2026-05-15 12:55:59'),('82ca4e6a-2fd4-475d-9fbb-803ea1f3857c','<p>Lỗi này bị sao vậy mọi người</p>','https://res.cloudinary.com/dhcbhatn9/image/upload/v1779275930/devops-aihub/avatars/Screenshot_2026-04-11_121008_bnl449.png','devops-aihub/avatars/Screenshot_2026-04-11_121008_bnl449','2026-04-24 03:52:38','2026-05-20 12:03:00'),('a1000001-0000-0000-0000-000000000001','I have a .NET Web API running on GitHub Actions. The pipeline works, but restore step is slow on every push. I want to cache NuGet packages correctly. What is the recommended way to do this?',NULL,NULL,'2026-03-28 10:00:00','2026-03-28 10:00:00'),('a1000002-0000-0000-0000-000000000002','My Jenkins pipeline builds the application successfully, but it fails when running docker build. I suspect the Dockerfile path or context is wrong. How should I debug this in Jenkins?',NULL,NULL,'2026-03-29 11:00:00','2026-03-29 11:00:00'),('a1000003-0000-0000-0000-000000000003','I deployed a service to Kubernetes and want Prometheus to scrape application metrics. I am unsure whether to use annotations, ServiceMonitor, or expose a separate metrics service.',NULL,NULL,'2026-03-30 12:00:00','2026-03-30 12:00:00'),('a1000004-0000-0000-0000-000000000004','Terraform apply keeps wanting to update Kubernetes resources even though I did not change the manifests. I think there is some drift or provider-specific field issue. What usually causes this?',NULL,NULL,'2026-03-31 13:00:00','2026-03-31 13:00:00');
